-- 自动生成：herb-export-site 生产 D1 预播种脚本
-- 由 functions/seed-data.js 导出，执行前请确保表尚未存在或容忍 IF NOT EXISTS

CREATE TABLE IF NOT EXISTS admins (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  username TEXT UNIQUE NOT NULL,
  password_hash TEXT NOT NULL,
  salt TEXT NOT NULL,
  created_at TEXT DEFAULT (datetime('now'))
);
CREATE TABLE IF NOT EXISTS categories (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  slug TEXT UNIQUE NOT NULL,
  name_zh TEXT NOT NULL,
  name_en TEXT NOT NULL,
  desc_zh TEXT DEFAULT '',
  desc_en TEXT DEFAULT '',
  icon TEXT DEFAULT 'leaf',
  sort_order INTEGER DEFAULT 0,
  created_at TEXT DEFAULT (datetime('now'))
);
CREATE TABLE IF NOT EXISTS products (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  slug TEXT UNIQUE NOT NULL,
  category_id INTEGER,
  name_zh TEXT NOT NULL,
  name_en TEXT NOT NULL,
  pinyin TEXT DEFAULT '',
  latin_name TEXT DEFAULT '',
  origin_zh TEXT DEFAULT '',
  origin_en TEXT DEFAULT '',
  part_zh TEXT DEFAULT '',
  part_en TEXT DEFAULT '',
  grade_zh TEXT DEFAULT '',
  grade_en TEXT DEFAULT '',
  spec_zh TEXT DEFAULT '',
  spec_en TEXT DEFAULT '',
  moisture TEXT DEFAULT '',
  ash TEXT DEFAULT '',
  package_zh TEXT DEFAULT '',
  package_en TEXT DEFAULT '',
  moq TEXT DEFAULT '',
  price_min REAL DEFAULT 0,
  price_max REAL DEFAULT 0,
  unit TEXT DEFAULT 'kg',
  shelf_life TEXT DEFAULT '',
  storage_zh TEXT DEFAULT '',
  storage_en TEXT DEFAULT '',
  desc_zh TEXT DEFAULT '',
  desc_en TEXT DEFAULT '',
  usage_zh TEXT DEFAULT '',
  usage_en TEXT DEFAULT '',
  certs TEXT DEFAULT '',
  image TEXT DEFAULT '',
  featured INTEGER DEFAULT 0,
  status TEXT DEFAULT 'active',
  sort_order INTEGER DEFAULT 0,
  views INTEGER DEFAULT 0,
  created_at TEXT DEFAULT (datetime('now')),
  updated_at TEXT DEFAULT (datetime('now'))
);
CREATE TABLE IF NOT EXISTS inquiries (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  product_id INTEGER,
  product_name TEXT DEFAULT '',
  name TEXT NOT NULL,
  email TEXT NOT NULL,
  phone TEXT DEFAULT '',
  company TEXT DEFAULT '',
  country TEXT DEFAULT '',
  quantity TEXT DEFAULT '',
  message TEXT DEFAULT '',
  status TEXT DEFAULT 'new',
  note TEXT DEFAULT '',
  created_at TEXT DEFAULT (datetime('now'))
);
CREATE TABLE IF NOT EXISTS company (
  id INTEGER PRIMARY KEY CHECK (id = 1),
  name_zh TEXT DEFAULT '', name_en TEXT DEFAULT '',
  intro_zh TEXT DEFAULT '', intro_en TEXT DEFAULT '',
  address_zh TEXT DEFAULT '', address_en TEXT DEFAULT '',
  phone TEXT DEFAULT '', whatsapp TEXT DEFAULT '',
  email TEXT DEFAULT '', website TEXT DEFAULT '',
  worktime_zh TEXT DEFAULT '', worktime_en TEXT DEFAULT '',
  year_founded TEXT DEFAULT '', employees TEXT DEFAULT '',
  factory_area TEXT DEFAULT '', main_market TEXT DEFAULT '',
  annual_output TEXT DEFAULT '',
  updated_at TEXT DEFAULT (datetime('now'))
);
CREATE TABLE IF NOT EXISTS certificates (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  name_zh TEXT NOT NULL, name_en TEXT NOT NULL,
  issuer_zh TEXT DEFAULT '', issuer_en TEXT DEFAULT '',
  image TEXT DEFAULT '',
  sort_order INTEGER DEFAULT 0
);
CREATE TABLE IF NOT EXISTS banners (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  title_zh TEXT DEFAULT '', title_en TEXT DEFAULT '',
  subtitle_zh TEXT DEFAULT '', subtitle_en TEXT DEFAULT '',
  image TEXT DEFAULT '',
  sort_order INTEGER DEFAULT 0,
  status INTEGER DEFAULT 1
);
CREATE TABLE IF NOT EXISTS i18n (
  key TEXT PRIMARY KEY,
  value_zh TEXT DEFAULT '',
  value_en TEXT DEFAULT ''
);
CREATE INDEX IF NOT EXISTS idx_products_cat ON products(category_id);
CREATE INDEX IF NOT EXISTS idx_products_status ON products(status);

-- categories
INSERT INTO categories (slug,name_zh,name_en,desc_zh,desc_en,icon,sort_order) VALUES ('roots-rhizomes','根及根茎类','Roots & Rhizomes','以根或根茎入药，是中药材出口量最大的品类，多用于滋补、活血、清热。','Roots and rhizomes are the largest exported TCM category, widely used for tonifying, blood activation and heat clearing.','root',1);
INSERT INTO categories (slug,name_zh,name_en,desc_zh,desc_en,icon,sort_order) VALUES ('flowers','花类','Flowers','以花蕾或花序入药，多含挥发油与黄酮，用于清热解表、疏肝理气。','Flower buds and inflorescences rich in volatile oils & flavonoids, used to release exterior and regulate qi.','flower',2);
INSERT INTO categories (slug,name_zh,name_en,desc_zh,desc_en,icon,sort_order) VALUES ('fruits-seeds','果实种子类','Fruits & Seeds','以成熟果实或种子入药，常用于消食、润肠、安神。','Mature fruits and seeds used for digestion, moistening intestines and calming the mind.','fruit',3);
INSERT INTO categories (slug,name_zh,name_en,desc_zh,desc_en,icon,sort_order) VALUES ('barks','皮类','Barks','以树皮或根皮入药，多在春秋采收，用于燥湿、温阳、止泻。','Tree or root bark harvested in spring/autumn, used to dry dampness, warm yang and stop diarrhea.','bark',4);
INSERT INTO categories (slug,name_zh,name_en,desc_zh,desc_en,icon,sort_order) VALUES ('whole-herbs','全草类','Whole Herbs','以全草或地上部分入药，富含挥发油，多用于解表化湿。','Whole aerial parts rich in volatile oil, mainly for releasing exterior and resolving dampness.','herb',5);
INSERT INTO categories (slug,name_zh,name_en,desc_zh,desc_en,icon,sort_order) VALUES ('leaves','叶类','Leaves','以叶片入药，多在花期前采收，用于疏散风热、清肺止咳。','Leaves collected before flowering, used to disperse wind-heat and clear the lung.','leaf',6);
INSERT INTO categories (slug,name_zh,name_en,desc_zh,desc_en,icon,sort_order) VALUES ('fungi-others','菌类及其他','Fungi & Others','真菌类及其他特殊来源药材，多用于扶正固本、利水渗湿。','Fungal and other special-source materials for strengthening resistance and draining dampness.','fungi',7);

-- products
INSERT INTO products (slug,category_id,name_zh,name_en,pinyin,latin_name,origin_zh,origin_en,part_zh,part_en,grade_zh,grade_en,spec_zh,spec_en,moisture,ash,package_zh,package_en,moq,price_min,price_max,unit,shelf_life,storage_zh,storage_en,desc_zh,desc_en,usage_zh,usage_en,certs,featured,status,sort_order) VALUES ('angelica-sinensis-root',(SELECT id FROM categories WHERE slug='roots-rhizomes'),'当归','Angelica Sinensis Root','Dang Gui','Radix Angelicae Sinensis','甘肃岷县','Minxian, Gansu','根','Root','一级 / 选货','Grade A / Selected','整枝 / 切片 / 粉末','Whole / Sliced / Powder','≤ 13%','≤ 7%','25kg/袋（编织袋或纸箱，可定制）','25kg/bag (woven bag or carton, customizable)','200 kg',9.8,16.5,'kg','24 个月 / 24 months','置阴凉干燥处，密封，防蛀防潮','Store in a cool dry place, sealed, protect from moisture & insects','伞形科当归的干燥根，主根粗长、支根少，断面黄白色，油润，香气浓郁。岷县当归挥发油与阿魏酸含量高，为公认道地产区。','Dried root of Angelica sinensis (Oliv.) Diels. Thick taproot with few branches, yellowish-white oily fracture and strong aroma. Minxian origin guarantees high volatile oil and ferulic acid content.','补血活血、调经止痛、润肠通便。用于血虚萎黄、月经不调、虚寒腹痛、肠燥便秘。','Tonifies blood, activates circulation, regulates menstruation and relieves pain. Used for blood deficiency, irregular menstruation, abdominal pain and constipation.','GMP, ISO9001, HACCP, COA, Phytosanitary Certificate',1,'active',1);
INSERT INTO products (slug,category_id,name_zh,name_en,pinyin,latin_name,origin_zh,origin_en,part_zh,part_en,grade_zh,grade_en,spec_zh,spec_en,moisture,ash,package_zh,package_en,moq,price_min,price_max,unit,shelf_life,storage_zh,storage_en,desc_zh,desc_en,usage_zh,usage_en,certs,featured,status,sort_order) VALUES ('astragalus-root',(SELECT id FROM categories WHERE slug='roots-rhizomes'),'黄芪','Astragalus Root','Huang Qi','Radix Astragali','甘肃陇西 / 山西浑源','Longxi Gansu / Hunyuan Shanxi','根','Root','一级 / 选货','Grade A / Selected','整枝 / 切片 / 粉末','Whole / Sliced / Powder','≤ 13%','≤ 7%','25kg/袋（编织袋或纸箱，可定制）','25kg/bag (woven bag or carton, customizable)','200 kg',6.2,11.8,'kg','24 个月 / 24 months','置阴凉干燥处，密封，防蛀防潮','Store in a cool dry place, sealed, protect from moisture & insects','豆科蒙古黄芪或膜荚黄芪的干燥根。条粗直、质硬而韧、断面纤维性强且显粉性，味微甜，嚼之有豆腥味。','Dried root of Astragalus membranaceus (Fisch.) Bge. or A. membranaceus var. mongholicus. Straight thick root, tough texture, fibrous powdery fracture, mildly sweet with beany note.','补气升阳、固表止汗、利水消肿、生津养血。用于气虚乏力、食少便溏、表虚自汗。','Tonifies qi and raises yang, consolidates the exterior, promotes diuresis. Used for qi deficiency fatigue, poor appetite and spontaneous sweating.','GMP, ISO9001, HACCP, COA, Phytosanitary Certificate',1,'active',2);
INSERT INTO products (slug,category_id,name_zh,name_en,pinyin,latin_name,origin_zh,origin_en,part_zh,part_en,grade_zh,grade_en,spec_zh,spec_en,moisture,ash,package_zh,package_en,moq,price_min,price_max,unit,shelf_life,storage_zh,storage_en,desc_zh,desc_en,usage_zh,usage_en,certs,featured,status,sort_order) VALUES ('ginseng-root-white-ginseng',(SELECT id FROM categories WHERE slug='roots-rhizomes'),'人参（生晒参）','Ginseng Root (White Ginseng)','Ren Shen','Radix et Rhizoma Ginseng','吉林抚松','Fusong, Jilin','根及根茎','Root & Rhizome','4~6 年生 / 特等','4–6 Years / Premium','整枝 / 切片 / 粉末','Whole / Sliced / Powder','≤ 13%','≤ 7%','25kg/袋（编织袋或纸箱，可定制）','25kg/bag (woven bag or carton, customizable)','200 kg',42,95,'kg','24 个月 / 24 months','置阴凉干燥处，密封，防蛀防潮','Store in a cool dry place, sealed, protect from moisture & insects','五加科人参的干燥根及根茎，主根呈纺锤形，表面黄白色，具疏浅断续的粗横纹及明显的纵皱，质较硬，断面粉性。','Dried root and rhizome of Panax ginseng C.A.Mey. Spindle-shaped main root, yellowish-white surface with transverse wrinkles, hard texture and farinaceous fracture.','大补元气、复脉固脱、补脾益肺、生津安神。用于体虚欲脱、脾虚食少、肺虚喘咳、津伤口渴。','Powerfully tonifies primordial qi, benefits spleen and lung, generates fluid and calms the mind. For collapse from severe deficiency, fatigue and dyspnea.','GMP, ISO9001, HACCP, COA, Phytosanitary Certificate',1,'active',3);
INSERT INTO products (slug,category_id,name_zh,name_en,pinyin,latin_name,origin_zh,origin_en,part_zh,part_en,grade_zh,grade_en,spec_zh,spec_en,moisture,ash,package_zh,package_en,moq,price_min,price_max,unit,shelf_life,storage_zh,storage_en,desc_zh,desc_en,usage_zh,usage_en,certs,featured,status,sort_order) VALUES ('panax-notoginseng-root',(SELECT id FROM categories WHERE slug='roots-rhizomes'),'三七','Panax Notoginseng Root','San Qi','Radix et Rhizoma Notoginseng','云南文山','Wenshan, Yunnan','根及根茎','Root & Rhizome','20~120 头','20–120 heads/500g','整枝 / 切片 / 粉末','Whole / Sliced / Powder','≤ 13%','≤ 7%','25kg/袋（编织袋或纸箱，可定制）','25kg/bag (woven bag or carton, customizable)','200 kg',48,125,'kg','24 个月 / 24 months','置阴凉干燥处，密封，防蛀防潮','Store in a cool dry place, sealed, protect from moisture & insects','五加科三七的干燥根及根茎。主根呈类圆锥形或圆柱形，表面灰褐色或灰黄色，有断续的纵皱纹及支根痕，体重质坚实，断面灰绿色或黄绿色。','Dried root and rhizome of Panax notoginseng (Burk.) F.H.Chen. Conical or cylindrical, grey-brown surface, hard and heavy, greyish-green fracture.','散瘀止血、消肿定痛。用于咯血、吐血、衄血、便血、崩漏、外伤出血、胸腹刺痛、跌扑肿痛。','Stops bleeding while dispersing blood stasis, reduces swelling and pain. For various bleeding syndromes and traumatic injuries.','GMP, ISO9001, HACCP, COA, Phytosanitary Certificate',1,'active',4);
INSERT INTO products (slug,category_id,name_zh,name_en,pinyin,latin_name,origin_zh,origin_en,part_zh,part_en,grade_zh,grade_en,spec_zh,spec_en,moisture,ash,package_zh,package_en,moq,price_min,price_max,unit,shelf_life,storage_zh,storage_en,desc_zh,desc_en,usage_zh,usage_en,certs,featured,status,sort_order) VALUES ('licorice-root',(SELECT id FROM categories WHERE slug='roots-rhizomes'),'甘草','Licorice Root','Gan Cao','Radix et Rhizoma Glycyrrhizae','内蒙古 / 甘肃','Inner Mongolia / Gansu','根及根茎','Root & Rhizome','一级 / 选货','Grade A / Selected','整枝 / 切片 / 粉末','Whole / Sliced / Powder','≤ 13%','≤ 7%','25kg/袋（编织袋或纸箱，可定制）','25kg/bag (woven bag or carton, customizable)','200 kg',4.2,8.6,'kg','24 个月 / 24 months','置阴凉干燥处，密封，防蛀防潮','Store in a cool dry place, sealed, protect from moisture & insects','豆科甘草、胀果甘草或光果甘草的干燥根及根茎。外皮松紧不一，表面红棕色或灰棕色，质坚实，断面略显纤维性，黄白色，粉性，味甜而特殊。','Dried root and rhizome of Glycyrrhiza uralensis / inflata / glabra. Reddish-brown surface, firm texture, fibrous farinaceous fracture, distinctly sweet taste.','补脾益气、清热解毒、祛痰止咳、缓急止痛、调和诸药。用于脾胃虚弱、倦怠乏力、咳嗽痰多、痈肿疮毒。','Tonifies spleen qi, clears heat and detoxifies, relieves cough, moderates spasm and harmonizes formulas.','GMP, ISO9001, HACCP, COA, Phytosanitary Certificate',0,'active',5);
INSERT INTO products (slug,category_id,name_zh,name_en,pinyin,latin_name,origin_zh,origin_en,part_zh,part_en,grade_zh,grade_en,spec_zh,spec_en,moisture,ash,package_zh,package_en,moq,price_min,price_max,unit,shelf_life,storage_zh,storage_en,desc_zh,desc_en,usage_zh,usage_en,certs,featured,status,sort_order) VALUES ('codonopsis-root',(SELECT id FROM categories WHERE slug='roots-rhizomes'),'党参','Codonopsis Root','Dang Shen','Radix Codonopsis','山西长治 / 甘肃','Changzhi Shanxi / Gansu','根','Root','一级 / 选货','Grade A / Selected','整枝 / 切片 / 粉末','Whole / Sliced / Powder','≤ 13%','≤ 7%','25kg/袋（编织袋或纸箱，可定制）','25kg/bag (woven bag or carton, customizable)','200 kg',12.5,22,'kg','24 个月 / 24 months','置阴凉干燥处，密封，防蛀防潮','Store in a cool dry place, sealed, protect from moisture & insects','桔梗科党参、素花党参或川党参的干燥根。呈长圆柱形，稍弯曲，表面黄棕色至灰棕色，根头部有多数疣状突起的茎痕及芽，习称"狮子盘头"。','Dried root of Codonopsis pilosula. Long cylindrical, slightly curved, yellowish-brown surface with characteristic "lion head" crown of stem scars.','健脾益肺、养血生津。用于脾肺气虚、食少倦怠、咳嗽虚喘、气血不足、面色萎黄。','Tonifies spleen and lung qi, nourishes blood and generates fluid. For qi deficiency, fatigue, poor appetite and chronic cough.','GMP, ISO9001, HACCP, COA, Phytosanitary Certificate',0,'active',6);
INSERT INTO products (slug,category_id,name_zh,name_en,pinyin,latin_name,origin_zh,origin_en,part_zh,part_en,grade_zh,grade_en,spec_zh,spec_en,moisture,ash,package_zh,package_en,moq,price_min,price_max,unit,shelf_life,storage_zh,storage_en,desc_zh,desc_en,usage_zh,usage_en,certs,featured,status,sort_order) VALUES ('danshen-salvia-root',(SELECT id FROM categories WHERE slug='roots-rhizomes'),'丹参','Danshen / Salvia Root','Dan Shen','Radix et Rhizoma Salviae Miltiorrhizae','山东 / 四川中江','Shandong / Zhongjiang Sichuan','根及根茎','Root & Rhizome','一级 / 选货','Grade A / Selected','整枝 / 切片 / 粉末','Whole / Sliced / Powder','≤ 13%','≤ 7%','25kg/袋（编织袋或纸箱，可定制）','25kg/bag (woven bag or carton, customizable)','200 kg',5.4,9.8,'kg','24 个月 / 24 months','置阴凉干燥处，密封，防蛀防潮','Store in a cool dry place, sealed, protect from moisture & insects','唇形科丹参的干燥根及根茎。根茎短粗，顶端有时残留茎基；根数条，长圆柱形，略弯曲，表面棕红色或暗棕红色，粗糙，具纵皱纹。','Dried root and rhizome of Salvia miltiorrhiza Bge. Short thick rhizome, several long cylindrical roots, dark reddish-brown wrinkled surface.','活血祛瘀、通经止痛、清心除烦、凉血消痈。用于胸痹心痛、月经不调、经闭痛经、疮疡肿痛。','Activates blood and dispels stasis, regulates menstruation, relieves pain and calms the heart. For chest pain, amenorrhea and dysmenorrhea.','GMP, ISO9001, HACCP, COA, Phytosanitary Certificate',0,'active',7);
INSERT INTO products (slug,category_id,name_zh,name_en,pinyin,latin_name,origin_zh,origin_en,part_zh,part_en,grade_zh,grade_en,spec_zh,spec_en,moisture,ash,package_zh,package_en,moq,price_min,price_max,unit,shelf_life,storage_zh,storage_en,desc_zh,desc_en,usage_zh,usage_en,certs,featured,status,sort_order) VALUES ('gastrodia-rhizome',(SELECT id FROM categories WHERE slug='roots-rhizomes'),'天麻','Gastrodia Rhizome','Tian Ma','Rhizoma Gastrodiae','云南昭通 / 贵州','Zhaotong Yunnan / Guizhou','块茎','Tuber','一级 / 选货','Grade A / Selected','整枝 / 切片 / 粉末','Whole / Sliced / Powder','≤ 13%','≤ 7%','25kg/袋（编织袋或纸箱，可定制）','25kg/bag (woven bag or carton, customizable)','200 kg',32,68,'kg','24 个月 / 24 months','置阴凉干燥处，密封，防蛀防潮','Store in a cool dry place, sealed, protect from moisture & insects','兰科天麻的干燥块茎。呈椭圆形或长条形，略扁，皱缩而稍弯曲，表面黄白色至黄棕色，有纵皱纹及由潜伏芽排列而成的多轮横环纹，习称"芝麻点"。','Dried tuber of Gastrodia elata Bl. Elliptical or elongated, slightly flattened, yellowish-brown with transverse rings.','息风止痉、平抑肝阳、祛风通络。用于小儿惊风、癫痫抽搐、破伤风、头痛眩晕、手足不遂、风湿痹痛。','Extinguishes wind and stops spasm, suppresses liver yang, unblocks collaterals. For convulsions, headache, dizziness and numbness.','GMP, ISO9001, HACCP, COA, Phytosanitary Certificate',0,'active',8);
INSERT INTO products (slug,category_id,name_zh,name_en,pinyin,latin_name,origin_zh,origin_en,part_zh,part_en,grade_zh,grade_en,spec_zh,spec_en,moisture,ash,package_zh,package_en,moq,price_min,price_max,unit,shelf_life,storage_zh,storage_en,desc_zh,desc_en,usage_zh,usage_en,certs,featured,status,sort_order) VALUES ('ophiopogon-tuber',(SELECT id FROM categories WHERE slug='roots-rhizomes'),'麦冬','Ophiopogon Tuber','Mai Dong','Radix Ophiopogonis','四川绵阳 / 浙江慈溪','Mianyang Sichuan / Cixi Zhejiang','块根','Root Tuber','一级 / 选货','Grade A / Selected','整枝 / 切片 / 粉末','Whole / Sliced / Powder','≤ 13%','≤ 7%','25kg/袋（编织袋或纸箱，可定制）','25kg/bag (woven bag or carton, customizable)','200 kg',15,29,'kg','24 个月 / 24 months','置阴凉干燥处，密封，防蛀防潮','Store in a cool dry place, sealed, protect from moisture & insects','百合科麦冬的干燥块根。呈纺锤形，两端略尖，表面黄白色或淡黄色，有细纵纹，质柔韧，断面黄白色，半透明，中柱细小。','Dried root tuber of Ophiopogon japonicus. Spindle-shaped with pointed ends, pale yellow flexible texture, translucent fracture.','养阴生津、润肺清心。用于肺燥干咳、阴虚痨嗽、喉痹咽痛、津伤口渴、内热消渴、心烦失眠。','Nourishes yin, generates fluid, moistens lung and clears heart. For dry cough, thirst and insomnia.','GMP, ISO9001, HACCP, COA, Phytosanitary Certificate',0,'active',9);
