INSERT INTO products (slug,category_id,name_zh,name_en,pinyin,latin_name,origin_zh,origin_en,part_zh,part_en,grade_zh,grade_en,spec_zh,spec_en,moisture,ash,package_zh,package_en,moq,price_min,price_max,unit,shelf_life,storage_zh,storage_en,desc_zh,desc_en,usage_zh,usage_en,certs,featured,status,sort_order) VALUES ('chrysanthemum-flower',(SELECT id FROM categories WHERE slug='flowers'),'菊花（杭白菊）','Chrysanthemum Flower','Ju Hua','Flos Chrysanthemi','浙江桐乡 / 安徽黄山','Tongxiang Zhejiang / Huangshan Anhui','头状花序','Capitulum','一级 / 选货','Grade A / Selected','整枝 / 切片 / 粉末','Whole / Sliced / Powder','≤ 13%','≤ 7%','25kg/袋（编织袋或纸箱，可定制）','25kg/bag (woven bag or carton, customizable)','200 kg',12,26,'kg','24 个月 / 24 months','置阴凉干燥处，密封，防蛀防潮','Store in a cool dry place, sealed, protect from moisture & insects','菊科菊的干燥头状花序，按产地和加工方法分为亳菊、滁菊、贡菊、杭菊。杭白菊花瓣洁白、花心金黄，气清香，味甘微苦，是出口量最大的花茶类药材。','Dried capitulum of Chrysanthemum morifolium Ramat. White petals with golden center, fragrant and slightly bitter. Most exported herbal tea flower.','散风清热、平肝明目、清热解毒。用于风热感冒、头痛眩晕、目赤肿痛、眼目昏花、疮痈肿毒。','Disperses wind and clears heat, calms the liver and improves vision. For headache, red eyes and blurred vision.','GMP, ISO9001, HACCP, COA, Phytosanitary Certificate',0,'active',2);
