INSERT INTO products (slug,category_id,name_zh,name_en,pinyin,latin_name,origin_zh,origin_en,part_zh,part_en,grade_zh,grade_en,spec_zh,spec_en,moisture,ash,package_zh,package_en,moq,price_min,price_max,unit,shelf_life,storage_zh,storage_en,desc_zh,desc_en,usage_zh,usage_en,certs,featured,status,sort_order) VALUES ('magnolia-flower-bud',(SELECT id FROM categories WHERE slug='flowers'),'辛夷','Magnolia Flower Bud','Xin Yi','Flos Magnoliae','河南南召 / 四川','Nanzhao Henan / Sichuan','花蕾','Flower Bud','一级 / 选货','Grade A / Selected','整枝 / 切片 / 粉末','Whole / Sliced / Powder','≤ 13%','≤ 7%','25kg/袋（编织袋或纸箱，可定制）','25kg/bag (woven bag or carton, customizable)','200 kg',13,22,'kg','24 个月 / 24 months','置阴凉干燥处，密封，防蛀防潮','Store in a cool dry place, sealed, protect from moisture & insects','木兰科望春花、玉兰或武当玉兰的干燥花蕾。呈长卵形，似毛笔头，基部常具短梗，苞片外表面密被灰白色或灰绿色茸毛，气芳香，味辛凉而稍苦。','Dried flower bud of Magnolia biondii / denudata / sprengeri. Brush-pen shaped, densely greyish-white tomentose, aromatic and pungent.','散风寒、通鼻窍。用于风寒头痛、鼻塞流涕、鼻鼽、鼻渊。','Disperses wind-cold and unblocks the nasal passages. For nasal congestion, sinusitis and cold-induced headache.','GMP, ISO9001, HACCP, COA, Phytosanitary Certificate',0,'active',4);
INSERT INTO products (slug,category_id,name_zh,name_en,pinyin,latin_name,origin_zh,origin_en,part_zh,part_en,grade_zh,grade_en,spec_zh,spec_en,moisture,ash,package_zh,package_en,moq,price_min,price_max,unit,shelf_life,storage_zh,storage_en,desc_zh,desc_en,usage_zh,usage_en,certs,featured,status,sort_order) VALUES ('goji-berry-wolfberry',(SELECT id FROM categories WHERE slug='fruits-seeds'),'枸杞子','Goji Berry / Wolfberry','Gou Qi Zi','Fructus Lycii','宁夏中宁','Zhongning, Ningxia','果实','Fruit','180/220/280/380 粒/50g','180/220/280/380 pcs per 50g','整枝 / 切片 / 粉末','Whole / Sliced / Powder','≤ 13%','≤ 7%','25kg/袋（编织袋或纸箱，可定制）','25kg/bag (woven bag or carton, customizable)','200 kg',8.5,16,'kg','24 个月 / 24 months','置阴凉干燥处，密封，防蛀防潮','Store in a cool dry place, sealed, protect from moisture & insects','茄科宁夏枸杞的干燥成熟果实。呈类纺锤形或椭圆形，表面红色或暗红色，顶端有小凸起状的花柱痕，果皮柔韧皱缩，果肉肉质柔润，种子 20~50 粒，味甜微酸。','Dried ripe fruit of Lycium barbarum L. Spindle-shaped red berries with wrinkled tender pericarp and sweet juicy pulp. Zhongning Ningxia is the authentic origin.','滋补肝肾、益精明目。用于虚劳精亏、腰膝酸痛、眩晕耳鸣、阳痿遗精、内热消渴、血虚萎黄、目昏不明。','Nourishes liver and kidney, benefits essence and improves vision. Widely used as a superfruit in food & beverage.','GMP, ISO9001, HACCP, COA, Phytosanitary Certificate',1,'active',1);
INSERT INTO products (slug,category_id,name_zh,name_en,pinyin,latin_name,origin_zh,origin_en,part_zh,part_en,grade_zh,grade_en,spec_zh,spec_en,moisture,ash,package_zh,package_en,moq,price_min,price_max,unit,shelf_life,storage_zh,storage_en,desc_zh,desc_en,usage_zh,usage_en,certs,featured,status,sort_order) VALUES ('schisandra-berry',(SELECT id FROM categories WHERE slug='fruits-seeds'),'五味子','Schisandra Berry','Wu Wei Zi','Fructus Schisandrae Chinensis','辽宁 / 吉林','Liaoning / Jilin','果实','Fruit','一级 / 选货','Grade A / Selected','整枝 / 切片 / 粉末','Whole / Sliced / Powder','≤ 13%','≤ 7%','25kg/袋（编织袋或纸箱，可定制）','25kg/bag (woven bag or carton, customizable)','200 kg',16,30,'kg','24 个月 / 24 months','置阴凉干燥处，密封，防蛀防潮','Store in a cool dry place, sealed, protect from moisture & insects','木兰科五味子的干燥成熟果实，习称"北五味子"。呈不规则的球形或扁球形，表面红色、紫红色或暗红色，皱缩，显油润，果肉柔软，味酸；种子肾形，有光泽。','Dried ripe fruit of Schisandra chinensis (Turcz.) Baill. Irregular red to dark-red wrinkled berries, sour taste, shiny kidney-shaped seeds.','收敛固涩、益气生津、补肾宁心。用于久嗽虚喘、梦遗滑精、遗尿尿频、久泻不止、自汗盗汗、津伤口渴、内热消渴、心悸失眠。','Astringes and consolidates, tonifies qi and generates fluid, calms the heart. For chronic cough, night sweats and insomnia.','GMP, ISO9001, HACCP, COA, Phytosanitary Certificate',0,'active',2);
INSERT INTO products (slug,category_id,name_zh,name_en,pinyin,latin_name,origin_zh,origin_en,part_zh,part_en,grade_zh,grade_en,spec_zh,spec_en,moisture,ash,package_zh,package_en,moq,price_min,price_max,unit,shelf_life,storage_zh,storage_en,desc_zh,desc_en,usage_zh,usage_en,certs,featured,status,sort_order) VALUES ('hawthorn-fruit',(SELECT id FROM categories WHERE slug='fruits-seeds'),'山楂','Hawthorn Fruit','Shan Zha','Fructus Crataegi','山东 / 河北承德','Shandong / Chengde Hebei','果实','Fruit','一级 / 选货','Grade A / Selected','山楂片 / 去核 / 整果','Slices / Pitted / Whole','≤ 13%','≤ 7%','25kg/袋（编织袋或纸箱，可定制）','25kg/bag (woven bag or carton, customizable)','200 kg',4,7.8,'kg','24 个月 / 24 months','置阴凉干燥处，密封，防蛀防潮','Store in a cool dry place, sealed, protect from moisture & insects','蔷薇科山里红或山楂的干燥成熟果实。为圆形片，皱缩不平，外皮红色，具皱纹，有灰白色小斑点，果肉深黄色至浅棕色，气微清香，味酸微甜。','Dried ripe fruit of Crataegus pinnatifida Bge. Red wrinkled slices with pale spots, sour and slightly sweet taste.','消食健胃、行气散瘀、化浊降脂。用于肉食积滞、胃脘胀满、泻痢腹痛、瘀血经闭、产后瘀阻、心腹刺痛、高脂血症。','Promotes digestion, moves qi and dispels blood stasis, lowers lipids. For food retention and hyperlipidemia.','GMP, ISO9001, HACCP, COA, Phytosanitary Certificate',0,'active',3);
INSERT INTO products (slug,category_id,name_zh,name_en,pinyin,latin_name,origin_zh,origin_en,part_zh,part_en,grade_zh,grade_en,spec_zh,spec_en,moisture,ash,package_zh,package_en,moq,price_min,price_max,unit,shelf_life,storage_zh,storage_en,desc_zh,desc_en,usage_zh,usage_en,certs,featured,status,sort_order) VALUES ('cassia-seed',(SELECT id FROM categories WHERE slug='fruits-seeds'),'决明子','Cassia Seed','Jue Ming Zi','Semen Cassiae','安徽 / 广西','Anhui / Guangxi','种子','Seed','一级 / 选货','Grade A / Selected','整枝 / 切片 / 粉末','Whole / Sliced / Powder','≤ 13%','≤ 7%','25kg/袋（编织袋或纸箱，可定制）','25kg/bag (woven bag or carton, customizable)','200 kg',3.2,6,'kg','24 个月 / 24 months','置阴凉干燥处，密封，防蛀防潮','Store in a cool dry place, sealed, protect from moisture & insects','豆科决明或小决明的干燥成熟种子。略呈菱方形或短圆柱形，两端平行倾斜，表面绿棕色或暗棕色，平滑有光泽，质坚硬，不易破碎，气微，味微苦。','Dried ripe seed of Cassia obtusifolia L. or C. tora L. Rhomboid to short cylindrical, glossy greenish-brown, very hard.','清热明目、润肠通便。用于目赤涩痛、羞明多泪、头痛眩晕、目暗不明、大便秘结。','Clears heat and brightens the eyes, moistens intestines to relieve constipation. Popular in slimming teas.','GMP, ISO9001, HACCP, COA, Phytosanitary Certificate',0,'active',4);
INSERT INTO products (slug,category_id,name_zh,name_en,pinyin,latin_name,origin_zh,origin_en,part_zh,part_en,grade_zh,grade_en,spec_zh,spec_en,moisture,ash,package_zh,package_en,moq,price_min,price_max,unit,shelf_life,storage_zh,storage_en,desc_zh,desc_en,usage_zh,usage_en,certs,featured,status,sort_order) VALUES ('coix-seed-job-s-tears',(SELECT id FROM categories WHERE slug='fruits-seeds'),'薏苡仁','Coix Seed (Job''s Tears)','Yi Yi Ren','Semen Coicis','贵州兴仁 / 福建','Xingren Guizhou / Fujian','种仁','Kernel','一级 / 选货','Grade A / Selected','整枝 / 切片 / 粉末','Whole / Sliced / Powder','≤ 13%','≤ 7%','25kg/袋（编织袋或纸箱，可定制）','25kg/bag (woven bag or carton, customizable)','200 kg',3,5.8,'kg','24 个月 / 24 months','置阴凉干燥处，密封，防蛀防潮','Store in a cool dry place, sealed, protect from moisture & insects','禾本科薏苡的干燥成熟种仁。呈宽卵形或长椭圆形，表面乳白色，光滑，偶有残存的黄褐色种皮，一端钝圆，另端较宽而微凹，质坚实，断面白色，粉性。','Dried ripe kernel of Coix lacryma-jobi var. ma-yuen. Milky-white smooth oval kernels, firm and starchy. Both food and medicine.','利水渗湿、健脾止泻、除痹、排脓、解毒散结。用于水肿、脚气、小便不利、脾虚泄泻、湿痹拘挛、肺痈、肠痈。','Promotes diuresis and drains dampness, strengthens spleen to stop diarrhea, discharges pus and dissipates nodules.','GMP, ISO9001, HACCP, COA, Phytosanitary Certificate',0,'active',5);
