INSERT INTO products (slug,category_id,name_zh,name_en,pinyin,latin_name,origin_zh,origin_en,part_zh,part_en,grade_zh,grade_en,spec_zh,spec_en,moisture,ash,package_zh,package_en,moq,price_min,price_max,unit,shelf_life,storage_zh,storage_en,desc_zh,desc_en,usage_zh,usage_en,certs,featured,status,sort_order) VALUES ('monk-fruit-luo-han-guo',(SELECT id FROM categories WHERE slug='fruits-seeds'),'罗汉果','Monk Fruit / Luo Han Guo','Luo Han Guo','Fructus Siraitiae','广西桂林永福','Yongfu, Guilin, Guangxi','果实','Fruit','一级 / 选货','Grade A / Selected','大果 / 中果 / 小果','Large / Medium / Small','≤ 13%','≤ 7%','25kg/袋（编织袋或纸箱，可定制）','25kg/bag (woven bag or carton, customizable)','200 kg',26,48,'kg','24 个月 / 24 months','置阴凉干燥处，密封，防蛀防潮','Store in a cool dry place, sealed, protect from moisture & insects','葫芦科罗汉果的干燥果实。呈卵形、椭圆形或球形，表面褐色、黄褐色或绿褐色，有深色斑块及黄色柔毛，体轻，质脆，果皮薄，易破，味极甜。罗汉果甜苷是天然零热量甜味剂。','Dried fruit of Siraitia grosvenorii. Oval brownish fruits with yellow pubescence, extremely sweet. Mogroside is a natural zero-calorie sweetener.','清热润肺、利咽开音、滑肠通便。用于肺热燥咳、咽痛失音、肠燥便秘。','Clears heat and moistens the lung, benefits the throat and relieves constipation. Widely used in natural sweetener industry.','GMP, ISO9001, HACCP, COA, Phytosanitary Certificate',0,'active',8);
INSERT INTO products (slug,category_id,name_zh,name_en,pinyin,latin_name,origin_zh,origin_en,part_zh,part_en,grade_zh,grade_en,spec_zh,spec_en,moisture,ash,package_zh,package_en,moq,price_min,price_max,unit,shelf_life,storage_zh,storage_en,desc_zh,desc_en,usage_zh,usage_en,certs,featured,status,sort_order) VALUES ('dried-tangerine-peel',(SELECT id FROM categories WHERE slug='fruits-seeds'),'陈皮','Dried Tangerine Peel','Chen Pi','Pericarpium Citri Reticulatae','广东新会','Xinhui, Guangdong','果皮','Peel','三年陈 / 五年陈 / 十年陈','Aged 3 / 5 / 10 Years','整枝 / 切片 / 粉末','Whole / Sliced / Powder','≤ 13%','≤ 7%','25kg/袋（编织袋或纸箱，可定制）','25kg/bag (woven bag or carton, customizable)','200 kg',7,14.5,'kg','24 个月 / 24 months','置阴凉干燥处，密封，防蛀防潮','Store in a cool dry place, sealed, protect from moisture & insects','芸香科橘及其栽培变种的干燥成熟果皮，采摘成熟果实，剥取果皮，晒干或低温干燥，陈久者良。新会陈皮为广陈皮上品，油室饱满，香气醇厚。','Dried ripe pericarp of Citrus reticulata Blanco, aged for better quality. Xinhui Guangdong is the premium origin with rich oil glands and mellow aroma.','理气健脾、燥湿化痰。用于脘腹胀满、食少吐泻、咳嗽痰多。','Regulates qi and strengthens the spleen, dries dampness and resolves phlegm. For abdominal distension and productive cough.','GMP, ISO9001, HACCP, COA, Phytosanitary Certificate',0,'active',9);
INSERT INTO products (slug,category_id,name_zh,name_en,pinyin,latin_name,origin_zh,origin_en,part_zh,part_en,grade_zh,grade_en,spec_zh,spec_en,moisture,ash,package_zh,package_en,moq,price_min,price_max,unit,shelf_life,storage_zh,storage_en,desc_zh,desc_en,usage_zh,usage_en,certs,featured,status,sort_order) VALUES ('amomum-fruit',(SELECT id FROM categories WHERE slug='fruits-seeds'),'砂仁','Amomum Fruit','Sha Ren','Fructus Amomi','广东阳春 / 云南','Yangchun Guangdong / Yunnan','果实','Fruit','一级 / 选货','Grade A / Selected','整枝 / 切片 / 粉末','Whole / Sliced / Powder','≤ 13%','≤ 7%','25kg/袋（编织袋或纸箱，可定制）','25kg/bag (woven bag or carton, customizable)','200 kg',46,82,'kg','24 个月 / 24 months','置阴凉干燥处，密封，防蛀防潮','Store in a cool dry place, sealed, protect from moisture & insects','姜科阳春砂、绿壳砂或海南砂的干燥成熟果实。呈椭圆形或卵圆形，有不明显的三棱，表面棕褐色，密生刺状突起，果皮薄而软，种子集结成团，气芳香而浓烈，味辛凉微苦。','Dried ripe fruit of Amomum villosum Lour. Oval with three vague ridges, densely spiny brown surface, strongly aromatic.','化湿开胃、温脾止泻、理气安胎。用于湿浊中阻、脘痞不饥、脾胃虚寒、呕吐泄泻、妊娠恶阻、胎动不安。','Transforms dampness and improves appetite, warms the spleen to stop diarrhea, calms the fetus.','GMP, ISO9001, HACCP, COA, Phytosanitary Certificate',0,'active',10);
INSERT INTO products (slug,category_id,name_zh,name_en,pinyin,latin_name,origin_zh,origin_en,part_zh,part_en,grade_zh,grade_en,spec_zh,spec_en,moisture,ash,package_zh,package_en,moq,price_min,price_max,unit,shelf_life,storage_zh,storage_en,desc_zh,desc_en,usage_zh,usage_en,certs,featured,status,sort_order) VALUES ('star-anise',(SELECT id FROM categories WHERE slug='fruits-seeds'),'八角茴香','Star Anise','Ba Jiao Hui Xiang','Fructus Anisi Stellati','广西梧州 / 云南','Wuzhou Guangxi / Yunnan','果实','Fruit','一级 / 选货','Grade A / Selected','整枝 / 切片 / 粉末','Whole / Sliced / Powder','≤ 13%','≤ 7%','25kg/袋（编织袋或纸箱，可定制）','25kg/bag (woven bag or carton, customizable)','200 kg',8.5,15.5,'kg','24 个月 / 24 months','置阴凉干燥处，密封，防蛀防潮','Store in a cool dry place, sealed, protect from moisture & insects','木兰科八角茴香的干燥成熟聚合果。为聚合果，多由 8 个蓇葖果组成，放射状排列于中轴上，外表面红棕色，有不规则皱纹，内表面淡棕色，平滑有光泽，气芳香，味辛甜。','Dried ripe fruit of Illicium verum Hook.f. Star-shaped aggregate of usually 8 follicles, reddish-brown, strongly aromatic and sweet-pungent.','温阳散寒、理气止痛。用于寒疝腹痛、肾虚腰痛、胃寒呕吐、脘腹冷痛。也是莽草酸（抗流感药物原料）的重要来源。','Warms yang and dispels cold, regulates qi and relieves pain. Also a key industrial source of shikimic acid.','GMP, ISO9001, HACCP, COA, Phytosanitary Certificate',0,'active',11);
INSERT INTO products (slug,category_id,name_zh,name_en,pinyin,latin_name,origin_zh,origin_en,part_zh,part_en,grade_zh,grade_en,spec_zh,spec_en,moisture,ash,package_zh,package_en,moq,price_min,price_max,unit,shelf_life,storage_zh,storage_en,desc_zh,desc_en,usage_zh,usage_en,certs,featured,status,sort_order) VALUES ('cinnamon-bark',(SELECT id FROM categories WHERE slug='barks'),'肉桂','Cinnamon Bark','Rou Gui','Cortex Cinnamomi','广西 / 广东','Guangxi / Guangdong','树皮','Bark','一级 / 选货','Grade A / Selected','桂皮 / 桂通 / 板桂','Quill / Tube / Slab','≤ 13%','≤ 7%','25kg/袋（编织袋或纸箱，可定制）','25kg/bag (woven bag or carton, customizable)','200 kg',5.5,10.5,'kg','24 个月 / 24 months','置阴凉干燥处，密封，防蛀防潮','Store in a cool dry place, sealed, protect from moisture & insects','樟科肉桂的干燥树皮。呈槽状或卷筒状，外表面灰棕色，稍粗糙，有不规则的细皱纹及横向突起的皮孔，内表面红棕色，略平坦，有细纵纹，划之显油痕，气香浓烈，味甜辣。','Dried bark of Cinnamomum cassia Presl. Channeled or quilled, grey-brown outside and reddish-brown inside, strongly aromatic, sweet and pungent.','补火助阳、引火归元、散寒止痛、温通经脉。用于阳痿宫冷、腰膝冷痛、肾虚作喘、虚阳上浮、眩晕目赤、心腹冷痛、虚寒吐泻、寒疝腹痛、痛经经闭。','Warms and supplements fire-yang, dispels cold and relieves pain, unblocks the meridians.','GMP, ISO9001, HACCP, COA, Phytosanitary Certificate',0,'active',1);
INSERT INTO products (slug,category_id,name_zh,name_en,pinyin,latin_name,origin_zh,origin_en,part_zh,part_en,grade_zh,grade_en,spec_zh,spec_en,moisture,ash,package_zh,package_en,moq,price_min,price_max,unit,shelf_life,storage_zh,storage_en,desc_zh,desc_en,usage_zh,usage_en,certs,featured,status,sort_order) VALUES ('eucommia-bark',(SELECT id FROM categories WHERE slug='barks'),'杜仲','Eucommia Bark','Du Zhong','Cortex Eucommiae','贵州遵义 / 四川','Zunyi Guizhou / Sichuan','树皮','Bark','一级 / 选货','Grade A / Selected','整枝 / 切片 / 粉末','Whole / Sliced / Powder','≤ 13%','≤ 7%','25kg/袋（编织袋或纸箱，可定制）','25kg/bag (woven bag or carton, customizable)','200 kg',7,13,'kg','24 个月 / 24 months','置阴凉干燥处，密封，防蛀防潮','Store in a cool dry place, sealed, protect from moisture & insects','杜仲科杜仲的干燥树皮。呈板片状或两边稍向内卷，外表面淡棕色或灰褐色，有明显的皱纹或纵裂槽纹，内表面暗紫色，光滑，质脆易折断，断面有细密银白色富弹性的橡胶丝相连。','Dried bark of Eucommia ulmoides Oliv. Flat slabs, grey-brown outside, dark purple inside; breaking reveals silvery elastic rubber threads.','补肝肾、强筋骨、安胎。用于肝肾不足、腰膝酸痛、筋骨无力、头晕目眩、妊娠漏血、胎动不安。','Tonifies liver and kidney, strengthens tendons and bones, calms the fetus. For lower back pain and weakness.','GMP, ISO9001, HACCP, COA, Phytosanitary Certificate',0,'active',2);
INSERT INTO products (slug,category_id,name_zh,name_en,pinyin,latin_name,origin_zh,origin_en,part_zh,part_en,grade_zh,grade_en,spec_zh,spec_en,moisture,ash,package_zh,package_en,moq,price_min,price_max,unit,shelf_life,storage_zh,storage_en,desc_zh,desc_en,usage_zh,usage_en,certs,featured,status,sort_order) VALUES ('magnolia-bark',(SELECT id FROM categories WHERE slug='barks'),'厚朴','Magnolia Bark','Hou Po','Cortex Magnoliae Officinalis','四川 / 湖北恩施','Sichuan / Enshi Hubei','干皮 / 根皮 / 枝皮','Trunk / Root / Branch Bark','一级 / 选货','Grade A / Selected','整枝 / 切片 / 粉末','Whole / Sliced / Powder','≤ 13%','≤ 7%','25kg/袋（编织袋或纸箱，可定制）','25kg/bag (woven bag or carton, customizable)','200 kg',9,16.5,'kg','24 个月 / 24 months','置阴凉干燥处，密封，防蛀防潮','Store in a cool dry place, sealed, protect from moisture & insects','木兰科厚朴或凹叶厚朴的干燥干皮、根皮及枝皮。干皮呈卷筒状或双卷筒状，外表面灰棕色或灰褐色，粗糙，有时呈鳞片状，较易剥落，内表面紫棕色或深紫褐色，较平滑，具细密纵纹，划之显油痕。','Dried bark of Magnolia officinalis Rehd. et Wils. Quilled, grey-brown rough outside, purple-brown smooth inside. Contains honokiol & magnolol.','燥湿消痰、下气除满。用于湿滞伤中、脘痞吐泻、食积气滞、腹胀便秘、痰饮喘咳。','Dries dampness and dissolves phlegm, descends qi and relieves fullness. Contains magnolol & honokiol, widely researched.','GMP, ISO9001, HACCP, COA, Phytosanitary Certificate',0,'active',3);
INSERT INTO products (slug,category_id,name_zh,name_en,pinyin,latin_name,origin_zh,origin_en,part_zh,part_en,grade_zh,grade_en,spec_zh,spec_en,moisture,ash,package_zh,package_en,moq,price_min,price_max,unit,shelf_life,storage_zh,storage_en,desc_zh,desc_en,usage_zh,usage_en,certs,featured,status,sort_order) VALUES ('phellodendron-bark',(SELECT id FROM categories WHERE slug='barks'),'黄柏','Phellodendron Bark','Huang Bai','Cortex Phellodendri Chinensis','四川 / 吉林','Sichuan / Jilin','树皮','Bark','一级 / 选货','Grade A / Selected','整枝 / 切片 / 粉末','Whole / Sliced / Powder','≤ 13%','≤ 7%','25kg/袋（编织袋或纸箱，可定制）','25kg/bag (woven bag or carton, customizable)','200 kg',11,19,'kg','24 个月 / 24 months','置阴凉干燥处，密封，防蛀防潮','Store in a cool dry place, sealed, protect from moisture & insects','芸香科黄檗（关黄柏）或黄皮树（川黄柏）的干燥树皮。呈板片状或浅槽状，外表面黄褐色或黄棕色，平坦或具纵沟纹，内表面暗黄色或淡棕色，具细密的纵棱纹，体轻，质硬，断面纤维性，呈裂片状分层，深黄色，味极苦。','Dried bark of Phellodendron chinense Schneid. or P. amurense Rupr. Yellow bitter bark, fibrous layered fracture. Rich in berberine.','清热燥湿、泻火除蒸、解毒疗疮。用于湿热泻痢、黄疸尿赤、带下阴痒、热淋涩痛、脚气痿躄、骨蒸劳热、盗汗、遗精、疮疡肿毒、湿疹湿疮。','Clears heat and dries dampness, purges fire and relieves steaming bone fever, detoxifies sores. Source of berberine.','GMP, ISO9001, HACCP, COA, Phytosanitary Certificate',0,'active',4);
INSERT INTO products (slug,category_id,name_zh,name_en,pinyin,latin_name,origin_zh,origin_en,part_zh,part_en,grade_zh,grade_en,spec_zh,spec_en,moisture,ash,package_zh,package_en,moq,price_min,price_max,unit,shelf_life,storage_zh,storage_en,desc_zh,desc_en,usage_zh,usage_en,certs,featured,status,sort_order) VALUES ('peppermint-field-mint',(SELECT id FROM categories WHERE slug='whole-herbs'),'薄荷','Peppermint / Field Mint','Bo He','Herba Menthae','江苏南通 / 安徽','Nantong Jiangsu / Anhui','地上部分','Aerial Part','一级 / 选货','Grade A / Selected','整枝 / 切片 / 粉末','Whole / Sliced / Powder','≤ 13%','≤ 7%','25kg/袋（编织袋或纸箱，可定制）','25kg/bag (woven bag or carton, customizable)','200 kg',5.2,9.5,'kg','24 个月 / 24 months','置阴凉干燥处，密封，防蛀防潮','Store in a cool dry place, sealed, protect from moisture & insects','唇形科薄荷的干燥地上部分。茎呈方柱形，有对生分枝，表面紫棕色或淡绿色，棱角处具茸毛，质脆，断面白色，髓部中空；叶对生，多卷缩破碎，揉搓后有特殊清凉香气，味辛凉。','Dried aerial part of Mentha haplocalyx Briq. Square stems, opposite leaves, strong cooling menthol aroma when crushed.','疏散风热、清利头目、利咽、透疹、疏肝行气。用于风热感冒、风温初起、头痛、目赤、喉痹、口疮、风疹、麻疹、胸胁胀闷。','Disperses wind-heat, clears head and eyes, benefits throat and releases rashes. Also soothes liver qi.','GMP, ISO9001, HACCP, COA, Phytosanitary Certificate',0,'active',1);
INSERT INTO products (slug,category_id,name_zh,name_en,pinyin,latin_name,origin_zh,origin_en,part_zh,part_en,grade_zh,grade_en,spec_zh,spec_en,moisture,ash,package_zh,package_en,moq,price_min,price_max,unit,shelf_life,storage_zh,storage_en,desc_zh,desc_en,usage_zh,usage_en,certs,featured,status,sort_order) VALUES ('houttuynia-herb',(SELECT id FROM categories WHERE slug='whole-herbs'),'鱼腥草','Houttuynia Herb','Yu Xing Cao','Herba Houttuyniae','四川 / 贵州','Sichuan / Guizhou','地上部分','Aerial Part','一级 / 选货','Grade A / Selected','整枝 / 切片 / 粉末','Whole / Sliced / Powder','≤ 13%','≤ 7%','25kg/袋（编织袋或纸箱，可定制）','25kg/bag (woven bag or carton, customizable)','200 kg',4.2,8,'kg','24 个月 / 24 months','置阴凉干燥处，密封，防蛀防潮','Store in a cool dry place, sealed, protect from moisture & insects','三白草科蕺菜的新鲜全草或干燥地上部分。茎呈扁圆柱形，扭曲，表面棕黄色，具纵棱数条，质脆易折断；叶互生，叶片卷折皱缩，展平后呈心形，搓碎有鱼腥气，味微涩。','Dried aerial part of Houttuynia cordata Thunb. Flattened twisted stems, heart-shaped leaves, characteristic fishy odor.','清热解毒、消痈排脓、利尿通淋。用于肺痈吐脓、痰热喘咳、热痢、热淋、痈肿疮毒。','Clears heat and detoxifies, discharges pus and promotes diuresis. For lung abscess, cough and urinary infection.','GMP, ISO9001, HACCP, COA, Phytosanitary Certificate',0,'active',2);
INSERT INTO products (slug,category_id,name_zh,name_en,pinyin,latin_name,origin_zh,origin_en,part_zh,part_en,grade_zh,grade_en,spec_zh,spec_en,moisture,ash,package_zh,package_en,moq,price_min,price_max,unit,shelf_life,storage_zh,storage_en,desc_zh,desc_en,usage_zh,usage_en,certs,featured,status,sort_order) VALUES ('patchouli-herb',(SELECT id FROM categories WHERE slug='whole-herbs'),'广藿香','Patchouli Herb','Guang Huo Xiang','Herba Pogostemonis','广东肇庆 / 海南','Zhaoqing Guangdong / Hainan','地上部分','Aerial Part','一级 / 选货','Grade A / Selected','整枝 / 切片 / 粉末','Whole / Sliced / Powder','≤ 13%','≤ 7%','25kg/袋（编织袋或纸箱，可定制）','25kg/bag (woven bag or carton, customizable)','200 kg',6.5,12,'kg','24 个月 / 24 months','置阴凉干燥处，密封，防蛀防潮','Store in a cool dry place, sealed, protect from moisture & insects','唇形科广藿香的干燥地上部分。茎略呈方柱形，多分枝，枝条稍曲折，表面被柔毛，质脆易折断，断面中部有髓；叶对生，皱缩成团，展平后叶片呈卵形或椭圆形，两面均被灰白色茸毛，气香特异，味微苦。','Dried aerial part of Pogostemon cablin (Blanco) Benth. Square branched stems, tomentose oval leaves, distinctive earthy aroma.','芳香化浊、和中止呕、发表解暑。用于湿浊中阻、脘痞呕吐、暑湿表证、湿温初起、发热倦怠、胸闷不舒、腹痛吐泻。','Aromatically transforms turbid dampness, harmonizes the middle to stop vomiting, releases summer-heat. Also source of patchouli oil.','GMP, ISO9001, HACCP, COA, Phytosanitary Certificate',0,'active',3);
INSERT INTO products (slug,category_id,name_zh,name_en,pinyin,latin_name,origin_zh,origin_en,part_zh,part_en,grade_zh,grade_en,spec_zh,spec_en,moisture,ash,package_zh,package_en,moq,price_min,price_max,unit,shelf_life,storage_zh,storage_en,desc_zh,desc_en,usage_zh,usage_en,certs,featured,status,sort_order) VALUES ('motherwort-herb',(SELECT id FROM categories WHERE slug='whole-herbs'),'益母草','Motherwort Herb','Yi Mu Cao','Herba Leonuri','河南 / 安徽','Henan / Anhui','地上部分','Aerial Part','一级 / 选货','Grade A / Selected','整枝 / 切片 / 粉末','Whole / Sliced / Powder','≤ 13%','≤ 7%','25kg/袋（编织袋或纸箱，可定制）','25kg/bag (woven bag or carton, customizable)','200 kg',3.8,7.2,'kg','24 个月 / 24 months','置阴凉干燥处，密封，防蛀防潮','Store in a cool dry place, sealed, protect from moisture & insects','唇形科益母草的新鲜或干燥地上部分。茎呈方柱形，四面凹下成纵沟，表面灰绿色或黄绿色，体轻质韧，断面中部有白色髓；叶交互对生，多皱缩破碎，完整者下部叶掌状 3 裂，上部叶羽状深裂或浅裂成 3 片。','Dried aerial part of Leonurus japonicus Houtt. Square grooved stems, palmately lobed leaves, used worldwide in women''s health.','活血调经、利尿消肿、清热解毒。用于月经不调、痛经经闭、恶露不尽、水肿尿少、疮疡肿毒。','Activates blood and regulates menstruation, promotes diuresis, clears heat and detoxifies.','GMP, ISO9001, HACCP, COA, Phytosanitary Certificate',0,'active',4);
INSERT INTO products (slug,category_id,name_zh,name_en,pinyin,latin_name,origin_zh,origin_en,part_zh,part_en,grade_zh,grade_en,spec_zh,spec_en,moisture,ash,package_zh,package_en,moq,price_min,price_max,unit,shelf_life,storage_zh,storage_en,desc_zh,desc_en,usage_zh,usage_en,certs,featured,status,sort_order) VALUES ('mugwort-ai-ye',(SELECT id FROM categories WHERE slug='leaves'),'艾叶','Mugwort / Ai Ye','Ai Ye','Folium Artemisiae Argyi','湖北蕲春 / 河南南阳','Qichun Hubei / Nanyang Henan','叶','Leaf','一级 / 选货','Grade A / Selected','艾叶 / 艾绒 / 艾条','Leaf / Moxa Wool / Moxa Stick','≤ 13%','≤ 7%','25kg/袋（编织袋或纸箱，可定制）','25kg/bag (woven bag or carton, customizable)','200 kg',4.5,8.5,'kg','24 个月 / 24 months','置阴凉干燥处，密封，防蛀防潮','Store in a cool dry place, sealed, protect from moisture & insects','菊科艾的干燥叶。多皱缩、破碎，有短柄；完整叶片展平后呈卵状椭圆形，羽状深裂，上表面灰绿色或深黄绿色，有稀疏的柔毛及腺点，下表面密生灰白色绒毛，质柔软，气清香，味苦。','Dried leaf of Artemisia argyi Lev. et Vant. Pinnately lobed leaves, grey-white tomentose beneath, aromatic and bitter. Widely used for moxibustion.','温经止血、散寒止痛、外用祛湿止痒。用于吐血、衄血、崩漏、月经过多、胎漏下血、少腹冷痛、经寒不调、宫冷不孕；外治皮肤瘙痒。','Warms the meridians to stop bleeding, dispels cold and relieves pain; externally relieves itching. Main material for moxibustion.','GMP, ISO9001, HACCP, COA, Phytosanitary Certificate',0,'active',1);
INSERT INTO products (slug,category_id,name_zh,name_en,pinyin,latin_name,origin_zh,origin_en,part_zh,part_en,grade_zh,grade_en,spec_zh,spec_en,moisture,ash,package_zh,package_en,moq,price_min,price_max,unit,shelf_life,storage_zh,storage_en,desc_zh,desc_en,usage_zh,usage_en,certs,featured,status,sort_order) VALUES ('mulberry-leaf',(SELECT id FROM categories WHERE slug='leaves'),'桑叶','Mulberry Leaf','Sang Ye','Folium Mori','浙江 / 四川','Zhejiang / Sichuan','叶','Leaf','一级 / 选货','Grade A / Selected','整枝 / 切片 / 粉末','Whole / Sliced / Powder','≤ 13%','≤ 7%','25kg/袋（编织袋或纸箱，可定制）','25kg/bag (woven bag or carton, customizable)','200 kg',4,7.5,'kg','24 个月 / 24 months','置阴凉干燥处，密封，防蛀防潮','Store in a cool dry place, sealed, protect from moisture & insects','桑科桑的干燥叶，初霜后采收者质佳，习称"霜桑叶"。多皱缩破碎，完整者有柄，叶片展平后呈卵形或宽卵形，上表面黄绿色或浅黄棕色，下表面颜色稍浅，叶脉突出，质脆，气微，味淡微苦涩。','Dried leaf of Morus alba L., best harvested after first frost ("Shuang Sang Ye"). Oval brittle leaves with prominent veins.','疏散风热、清肺润燥、清肝明目。用于风热感冒、肺热燥咳、头晕头痛、目赤昏花。','Disperses wind-heat, clears and moistens the lung, clears liver and improves vision. Popular in herbal tea blends.','GMP, ISO9001, HACCP, COA, Phytosanitary Certificate',0,'active',2);
INSERT INTO products (slug,category_id,name_zh,name_en,pinyin,latin_name,origin_zh,origin_en,part_zh,part_en,grade_zh,grade_en,spec_zh,spec_en,moisture,ash,package_zh,package_en,moq,price_min,price_max,unit,shelf_life,storage_zh,storage_en,desc_zh,desc_en,usage_zh,usage_en,certs,featured,status,sort_order) VALUES ('loquat-leaf',(SELECT id FROM categories WHERE slug='leaves'),'枇杷叶','Loquat Leaf','Pi Pa Ye','Folium Eriobotryae','福建 / 浙江','Fujian / Zhejiang','叶','Leaf','一级 / 选货','Grade A / Selected','净叶 / 蜜炙 / 去毛','Raw / Honey-fried / Defuzzed','≤ 13%','≤ 7%','25kg/袋（编织袋或纸箱，可定制）','25kg/bag (woven bag or carton, customizable)','200 kg',5,9,'kg','24 个月 / 24 months','置阴凉干燥处，密封，防蛀防潮','Store in a cool dry place, sealed, protect from moisture & insects','蔷薇科枇杷的干燥叶。呈长圆形或倒卵形，先端尖，基部楔形，边缘有疏锯齿，近基部全缘，上表面灰绿色、黄棕色或红棕色，较光滑，下表面密被黄色绒毛，主脉显著突起，质脆，味微苦。','Dried leaf of Eriobotrya japonica (Thunb.) Lindl. Oblong leaves with serrated margins, yellow tomentose underside.','清肺止咳、降逆止呕。用于肺热咳嗽、气逆喘急、胃热呕逆、烦热口渴。','Clears the lung and stops cough, directs rebellious qi downward to stop vomiting.','GMP, ISO9001, HACCP, COA, Phytosanitary Certificate',0,'active',3);
INSERT INTO products (slug,category_id,name_zh,name_en,pinyin,latin_name,origin_zh,origin_en,part_zh,part_en,grade_zh,grade_en,spec_zh,spec_en,moisture,ash,package_zh,package_en,moq,price_min,price_max,unit,shelf_life,storage_zh,storage_en,desc_zh,desc_en,usage_zh,usage_en,certs,featured,status,sort_order) VALUES ('reishi-lingzhi-mushroom',(SELECT id FROM categories WHERE slug='fungi-others'),'灵芝（赤芝）','Reishi / Lingzhi Mushroom','Ling Zhi','Ganoderma Lucidum','浙江龙泉 / 福建武夷山','Longquan Zhejiang / Wuyishan Fujian','子实体','Fruiting Body','一级 / 选货','Grade A / Selected','整芝 / 切片 / 孢子粉 / 提取物','Whole / Sliced / Spore Powder / Extract','≤ 13%','≤ 7%','25kg/袋（编织袋或纸箱，可定制）','25kg/bag (woven bag or carton, customizable)','200 kg',22,48,'kg','24 个月 / 24 months','置阴凉干燥处，密封，防蛀防潮','Store in a cool dry place, sealed, protect from moisture & insects','多孔菌科真菌赤芝或紫芝的干燥子实体。菌盖木栓质，肾形、半圆形或近圆形，皮壳坚硬，黄褐色至红褐色，有光泽，具环状棱纹和辐射状皱纹，菌肉白色至淡棕色，味苦。','Dried fruiting body of Ganoderma lucidum (Curtis) P.Karst. Kidney-shaped woody cap, reddish-brown and glossy with concentric rings.','补气安神、止咳平喘。用于心神不宁、失眠心悸、肺虚咳喘、虚劳短气、不思饮食。','Tonifies qi and calms the spirit, relieves cough and asthma. Popular worldwide as an adaptogen.','GMP, ISO9001, HACCP, COA, Phytosanitary Certificate',1,'active',1);
INSERT INTO products (slug,category_id,name_zh,name_en,pinyin,latin_name,origin_zh,origin_en,part_zh,part_en,grade_zh,grade_en,spec_zh,spec_en,moisture,ash,package_zh,package_en,moq,price_min,price_max,unit,shelf_life,storage_zh,storage_en,desc_zh,desc_en,usage_zh,usage_en,certs,featured,status,sort_order) VALUES ('poria-fu-ling',(SELECT id FROM categories WHERE slug='fungi-others'),'茯苓','Poria / Fu Ling','Fu Ling','Poria cocos','云南 / 湖北罗田','Yunnan / Luotian Hubei','菌核','Sclerotium','一级 / 选货','Grade A / Selected','白茯苓丁 / 茯苓块 / 茯苓皮 / 茯神','White Cubes / Blocks / Peel / Fu Shen','≤ 13%','≤ 7%','25kg/袋（编织袋或纸箱，可定制）','25kg/bag (woven bag or carton, customizable)','200 kg',6.5,11.5,'kg','24 个月 / 24 months','置阴凉干燥处，密封，防蛀防潮','Store in a cool dry place, sealed, protect from moisture & insects','多孔菌科真菌茯苓的干燥菌核，多寄生于马尾松或赤松的根上。呈类球形、椭圆形、扁圆形或不规则团块，外皮薄而粗糙，棕褐色至黑褐色，有明显的皱缩纹理，体重质坚实，断面颗粒性，白色或淡红色，粘牙。','Dried sclerotium of Poria cocos (Schw.) Wolf, parasitic on pine roots. Firm globular mass, brown rough outer skin, white granular fracture.','利水渗湿、健脾、宁心。用于水肿尿少、痰饮眩悸、脾虚食少、便溏泄泻、心神不安、惊悸失眠。','Promotes diuresis and drains dampness, strengthens the spleen and calms the mind.','GMP, ISO9001, HACCP, COA, Phytosanitary Certificate',0,'active',2);
INSERT INTO products (slug,category_id,name_zh,name_en,pinyin,latin_name,origin_zh,origin_en,part_zh,part_en,grade_zh,grade_en,spec_zh,spec_en,moisture,ash,package_zh,package_en,moq,price_min,price_max,unit,shelf_life,storage_zh,storage_en,desc_zh,desc_en,usage_zh,usage_en,certs,featured,status,sort_order) VALUES ('cordyceps-sinensis',(SELECT id FROM categories WHERE slug='fungi-others'),'冬虫夏草','Cordyceps Sinensis','Dong Chong Xia Cao','Cordyceps sinensis','青海玉树 / 西藏那曲','Yushu Qinghai / Nagqu Tibet','复合体','Complex (fungus + larva)','2000/3000/4000 条/kg','2000/3000/4000 pcs per kg','整枝 / 切片 / 粉末','Whole / Sliced / Powder','≤ 13%','≤ 7%','25kg/袋（编织袋或纸箱，可定制）','25kg/bag (woven bag or carton, customizable)','100 g',18000,32000,'kg','24 个月 / 24 months','置阴凉干燥处，密封，防蛀防潮','Store in a cool dry place, sealed, protect from moisture & insects','麦角菌科真菌冬虫夏草菌寄生在蝙蝠蛾科昆虫幼虫上的子座和幼虫尸体的干燥复合体。虫体似蚕，表面深黄色至黄棕色，有环纹 20~30 个，足 8 对；子座细长圆柱形，表面深棕色至棕褐色，气微腥，味微苦。需提供濒危物种进出口许可文件。','Dried complex of the fungus Cordyceps sinensis and its host larva. Caterpillar-shaped body with a slender stem-like stroma. CITES documentation required for export.','补肾益肺、止血化痰。用于肾虚精亏、阳痿遗精、腰膝酸痛、久咳虚喘、劳嗽痰血。','Tonifies kidney and lung, stops bleeding and resolves phlegm. For impotence, chronic cough and lower back pain.','GMP, ISO9001, HACCP, COA, Phytosanitary Certificate',0,'active',3);

-- company
INSERT INTO company (id,name_zh,name_en,intro_zh,intro_en,address_zh,address_en,phone,whatsapp,email,website,worktime_zh,worktime_en,year_founded,employees,factory_area,main_market,annual_output) VALUES (1,'华源堂中药材进出口有限公司','Huayuan Tang Chinese Herbs Import & Export Co., Ltd.','公司始创于 1993 年，总部位于中国药都安徽亳州，是集种植基地、饮片加工、质量检测与国际贸易于一体的中药材专业供应商。我们在甘肃、云南、宁夏、四川、广西等道地产区建有 12 个合作种植基地与 3 个现代化加工车间，年加工能力逾 8,000 吨。产品远销欧盟、美国、日本、韩国、东南亚及中东等 40 多个国家和地区，长期为保健品、功能食品、草本茶、化妆品及制药企业提供稳定的原料供应与 OEM/ODM 服务。','Founded in 1993 and headquartered in Bozhou (China''s herb capital), we are a professional supplier integrating planting bases, decoction-piece processing, quality testing and international trade. We operate 12 partner farms and 3 modern processing workshops across authentic producing regions including Gansu, Yunnan, Ningxia, Sichuan and Guangxi, with over 8,000 tons annual capacity. Our products are exported to 40+ countries and regions in the EU, US, Japan, Korea, Southeast Asia and the Middle East, serving nutraceutical, functional food, herbal tea, cosmetic and pharmaceutical manufacturers with stable supply and OEM/ODM services.','安徽省亳州市谯城区药材交易中心 A 区 18 号','No.18, Block A, Herb Trading Center, Qiaocheng District, Bozhou, Anhui, China','+86-558-8888-6688','+86-138-0567-8888','export@huayuantang-herb.com','www.huayuantang-herb.com','周一至周六 8:30–18:00（GMT+8）','Mon–Sat 8:30–18:00 (GMT+8)','1993','260+','32,000 m²','欧盟 / 美国 / 日韩 / 东南亚 / 中东（40+ 国家）','8,000 吨 / 年');

